package com.anharness.app.sandbox

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * [T-asset-manifest] Manifest build/encode/verify contract + interop with
 * the committed manifest generated by scripts/generate_asset_manifest.py.
 */
class AssetManifestTest {

    private fun files(vararg pairs: Pair<String, String>) =
        pairs.associate { (p, s) -> p to s.toByteArray(Charsets.UTF_8) }

    @Test
    fun `build and verify round-trip`() {
        val f = files("default_mount/a.sh" to "echo hi", "remote/server.py" to "print(1)")
        val m = AssetManifest.build(f)
        assertEquals(AssetManifest.VerifyResult.Ok, AssetManifest.verify(m, f))
    }

    @Test
    fun `encode decode round-trip deterministic order`() {
        val f = files("b" to "2", "a" to "1")
        val m = AssetManifest.build(f)
        assertEquals(listOf("a", "b"), m.entries.map { it.path })
        val back = AssetManifest.decode(AssetManifest.encode(m))!!
        assertEquals(m, back)
    }

    @Test
    fun `tampered content detected`() {
        val f = files("a" to "original")
        val m = AssetManifest.build(f)
        val tampered = files("a" to "modified")
        val r = AssetManifest.verify(m, tampered)
        assertTrue(r is AssetManifest.VerifyResult.Mismatch)
        assertEquals(listOf("a"), (r as AssetManifest.VerifyResult.Mismatch).paths)
    }

    @Test
    fun `same-length tamper still caught by hash`() {
        val f = files("a" to "aaaa")
        val m = AssetManifest.build(f)
        val r = AssetManifest.verify(m, files("a" to "bbbb"))
        assertTrue(r is AssetManifest.VerifyResult.Mismatch)
    }

    @Test
    fun `missing file detected`() {
        val m = AssetManifest.build(files("a" to "1", "b" to "2"))
        val r = AssetManifest.verify(m, files("a" to "1"))
        assertTrue(r is AssetManifest.VerifyResult.Missing)
        assertEquals(listOf("b"), (r as AssetManifest.VerifyResult.Missing).paths)
    }

    @Test
    fun `extra file detected`() {
        val m = AssetManifest.build(files("a" to "1"))
        val r = AssetManifest.verify(m, files("a" to "1", "evil" to "x"))
        assertTrue(r is AssetManifest.VerifyResult.Extra)
        assertEquals(listOf("evil"), (r as AssetManifest.VerifyResult.Extra).paths)
    }

    @Test
    fun `malformed or wrong-version manifest rejected`() {
        assertNull(AssetManifest.decode("not json"))
        assertNull(AssetManifest.decode("""{"version":99,"files":[]}"""))
        assertNull(AssetManifest.decode("""{"files":[]}"""))
    }

    @Test
    fun `committed manifest verifies against real assets`() {
        // Interop: the python generator and the Kotlin verifier must agree
        // byte-for-byte on the committed asset tree.
        val assetsDir = File("src/main/assets")
        val manifestFile = File(assetsDir, AssetManifest.MANIFEST_ASSET_PATH)
        assertTrue("manifest must exist (run scripts/generate_asset_manifest.py)", manifestFile.exists())
        val manifest = AssetManifest.decode(manifestFile.readText())!!
        val actual = mutableMapOf<String, ByteArray>()
        for (dir in listOf("default_mount", "remote")) {
            File(assetsDir, dir).walkTopDown().filter { it.isFile }.forEach { f ->
                val rel = f.relativeTo(assetsDir).path.replace(File.separatorChar, '/')
                actual[rel] = f.readBytes()
            }
        }
        assertEquals(AssetManifest.VerifyResult.Ok, AssetManifest.verify(manifest, actual))
    }
}